int i = 1;
while (i <= 5) {
    printf("%d ", i);
    i++;              /* 이걸 빠뜨리면 무한 루프 */
}
printf("\n");         /* 1 2 3 4 5 */

int n = 100;

while (n < 10) { printf("while\n"); }      /* 한 번도 실행 안 됨 */

do { printf("do-while\n"); } while (n < 10); /* 한 번은 실행됨 */

int i = 10;
do {
    printf("%d ", i);
    i++;
} while (i < 5);
printf("\n");

for (int i = 0; i < 5; i++) {
    printf("%d ", i);
}
printf("\n");   /* 0 1 2 3 4 */

int sum = 0;
for (int i = 1; i <= 5; i++) {
    sum += i;
}
printf("%d\n", sum);

int arr[5] = {3, 8, 1, 9, 4};
int i, found = -1;

for (i = 0; i < 5; i++) {
    if (arr[i] == 1) {
        found = i;
        break;        /* 찾았으니 그만 */
    }
}
printf("%d\n", found);   /* 2 */

for (int i = 1; i <= 10; i++) {
    if (i % 2 != 0) continue;   /* 홀수는 건너뛴다 */
    printf("%d ", i);
}
printf("\n");   /* 2 4 6 8 10 */

int i = 0;
while (i < 10) {
    if (i % 2) continue;   /* i가 안 늘어나 무한 루프! */
    printf("%d ", i);
    i++;
}

int sum = 0;
for (int i = 1; i <= 10; i++) {
    if (i == 5) break;
    sum += i;
}
printf("%d\n", sum);

for (int i = 1; i <= 3; i++) {
    for (int j = 1; j <= 3; j++) {
        printf("%d*%d=%d ", i, j, i * j);
    }
    printf("\n");
}

int cnt = 0;
for (int i = 0; i < 3; i++)
    for (int j = 0; j < 4; j++)
        cnt++;
printf("%d\n", cnt);

while (1) {
    int cmd;
    printf("명령(0=종료): ");
    if (scanf("%d", &cmd) != 1) break;
    if (cmd == 0) break;
    printf("처리: %d\n", cmd);
}

